import assert from 'node:assert/strict';
import SuperJSON from './dist/index.js';
import {normalizeStackNewlines} from './dist/error-stack.js';
import {sanitizeMessage} from './dist/error-sanitizer.js';
assert.equal(normalizeStackNewlines('a\r\nb\rc'),'a\nb\nc');
assert.equal(sanitizeMessage('x a@b.com http://foo.com 1.2.3.4'), 'x [redacted] [redacted] [redacted]');
const s=new SuperJSON({errorStack:{mode:'off'}}); s.allowErrorProps('stack'); assert.ok(!('stack' in s.serialize(new Error('test')).json));
const f=new SuperJSON({errorStack:{mode:'frames',includeCauses:'deep',sanitizeMessage:true}}); f.allowErrorProps('stackFrames'); const e=new Error('http://foo.com',{cause:new Error('a@b.com')}); e.stack='Error: http://foo.com\n    at /app/test.js:1:1'; const p=f.serialize(new Map([['x',e]])); console.log(JSON.stringify(p)); const r=f.parse(f.stringify(new Map([['x',e]]))).get('x'); console.log(r, r.cause, r.stackFrames);
